import{c as e,Q as o,j as n,m as r}from"./chunks/framework.BXc4yaFE.js";const h=JSON.parse('{"title":"Prompt Caching × Management × Engineering — 整合研究報告","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/2026-06-03-prompt-caching-management-engineering.md","filePath":"research/reports/2026-06-03-prompt-caching-management-engineering.md","lastUpdated":1780842316000}'),i={name:"research/reports/2026-06-03-prompt-caching-management-engineering.md"};function a(s,t,c,d,l,g){return o(),n("div",null,[...t[0]||(t[0]=[r(`<h1 id="prompt-caching-×-management-×-engineering-—-整合研究報告" tabindex="-1">Prompt Caching × Management × Engineering — 整合研究報告 <a class="header-anchor" href="#prompt-caching-×-management-×-engineering-—-整合研究報告" aria-label="Permalink to &quot;Prompt Caching × Management × Engineering — 整合研究報告&quot;">​</a></h1><p><strong>日期</strong>：2026-06-03 | <strong>Branch</strong>：<code>feature/prompt-caching-engineering-research</code><strong>研究方法</strong>：以平行 researcher subagents fan-out 模擬 overnight-research 的搜尋階段（盤點既有材料 → 三主題缺口並行調查 → 全文歸檔 → 整合驗證）；信度分層歸檔對應 research-hub:deep、缺口收斂對應 autoresearch 的迭代精神。<strong>誠實標注：未直接呼叫該三 skill 的 SKILL runner，而是用其方法論骨架由主 agent 編排。</strong><strong>Target 假設（釘死）</strong>：所有發現以「可套用到本 cc-workspace harness」為驗收終點 — 見姊妹計劃書 <code>2026-06-03-prompt-harness-action-plan.md</code><strong>信度標注</strong>：🟢 官方一手（provider docs / arXiv 原文）｜🟡 論文 peer-reviewable｜🟠 社群二手（blog / GitHub issue / 工具方文章）</p><hr><h2 id="執行摘要" tabindex="-1">執行摘要 <a class="header-anchor" href="#執行摘要" aria-label="Permalink to &quot;執行摘要&quot;">​</a></h2><p>Prompt 三主題在 2026 年已從「技巧」演化為「工程紀律」。本報告整合既有 5 篇論文 + 3 份 best-practices，並補齊三主題的系統性缺口，得出三個核心結論：</p><ol><li><strong>Caching 是經濟學，不是開關</strong>：跨 provider 的回本門檻差異巨大（OpenAI/Google-implicit 第 1 次重用即回本；Anthropic 5min TTL 需 ≥2 次、1h TTL 需 ≥3 次）。選錯 TTL 或 placement 會讓快取「越用越貴」。</li><li><strong>Management 是三主題中缺口最大、ROI 最高的一塊</strong>：versioning / registry / A/B / 注入防禦在既有材料中近乎空白，而這正是把「prompt 從 demo 推到 production」的關鍵基礎設施。</li><li><strong>Engineering 隨模型能力非線性反轉</strong>：更強的模型需要<strong>更簡單</strong>的 prompt。<code>prompting-inversion</code>（GPT）在 Claude Opus 4.8 上以<strong>字面化 + effort 旋鈕</strong>的形式獲得官方一手確認 🟢 —「shallow reasoning 是 effort 問題，不是 prompt 問題」。</li></ol><p>貫穿三主題的主線：<strong>靜態前綴穩定（caching）→ 版本可追溯（management）→ 用 eval 而非直覺迭代（engineering）</strong>，三者構成一條 prompt 生命週期的流水線。</p><hr><h2 id="section-a-prompt-caching-—-經濟學與失效控制" tabindex="-1">Section A：Prompt Caching — 經濟學與失效控制 <a class="header-anchor" href="#section-a-prompt-caching-—-經濟學與失效控制" aria-label="Permalink to &quot;Section A：Prompt Caching — 經濟學與失效控制&quot;">​</a></h2><h3 id="a-1-跨-provider-成本模型-缺口補齊-🟢" tabindex="-1">A.1 跨 Provider 成本模型（缺口補齊）🟢 <a class="header-anchor" href="#a-1-跨-provider-成本模型-缺口補齊-🟢" aria-label="Permalink to &quot;A.1 跨 Provider 成本模型（缺口補齊）🟢&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provider / 模式</th><th>Cache write 加價</th><th>Cache read 折扣</th><th>Storage 費</th><th>最小 token</th><th>回本門檻</th></tr></thead><tbody><tr><td>Anthropic 5min TTL</td><td>+25%</td><td>90% off（0.1×）</td><td>無</td><td>Opus 4.5/4.6/4.7/4.8 + Sonnet 4.5/4.6 = <strong>1,024</strong>；<strong>僅 Haiku 4.5 = 4,096</strong>（官方表親驗）</td><td><strong>≥2 次讀取</strong></td></tr><tr><td>Anthropic 1h TTL</td><td>+100%</td><td>90% off</td><td>無</td><td>同上</td><td><strong>≥3 次讀取</strong></td></tr><tr><td>OpenAI（自動）</td><td>無</td><td><strong>up to 90% off</strong>（官方原文，gpt-5.x；docs 親驗）</td><td>無</td><td>1,024（親驗）</td><td><strong>≥1 次即回本</strong></td></tr><tr><td>Google Explicit</td><td>無</td><td>90% off（Flash read $0.03 vs $0.30，親驗）</td><td>有（2.5 Pro <strong>$4.50/M·hr</strong>，docs 親驗）</td><td>Pro 2,048 / Flash 1,024</td><td>storage 費主導，需高使用率</td></tr><tr><td>Google Implicit（2025 新）</td><td>無</td><td>~75% off 🟠（researcher-reported，官方 pricing 頁未明列百分比，未獨立驗證）</td><td>無</td><td>同上</td><td><strong>≥1 次即回本</strong></td></tr></tbody></table><p>來源：<strong>Anthropic Pricing/Prompt-Caching、OpenAI Prompt Caching Guide、Google AI Pricing 三者經主 agent WebFetch 親驗（🟢）</strong>；唯 Google Implicit 75% 折扣官方 pricing 頁未列具體百分比，降標 🟠。OpenAI 官方原文：&quot;reduce input token costs by up to 90%&quot; + &quot;Caching happens automatically, with no explicit action needed or extra cost&quot;。</p><p><strong>決策框架</strong>：</p><ul><li>偶發、短重用 → OpenAI / Google-implicit（無寫入成本，立即回本）。</li><li>高頻、同一前綴連發 → Anthropic 5min（最快收斂，2 次回本）。</li><li>Agentic long-horizon（工具迴圈 &gt;5min）→ Anthropic 1h TTL（避免 mid-loop cache miss），代價是 2× 寫入費。</li><li>大型靜態文件跨 session 批查（RAG / 法律）→ Google Explicit（storage 費換取跨 session 保留），但須先算 storage 是否吃掉折扣。</li></ul><h3 id="a-2-caching-long-context-協同-🟢🟡" tabindex="-1">A.2 Caching + Long-context 協同 🟢🟡 <a class="header-anchor" href="#a-2-caching-long-context-協同-🟢🟡" aria-label="Permalink to &quot;A.2 Caching + Long-context 協同 🟢🟡&quot;">​</a></h3><ol><li>Anthropic 1M context <strong>無 premium surcharge</strong>，900k 與 9k 請求同 per-token 費率；caching 折扣全 context 統一適用。</li><li><strong>Batch + Caching multiplier 疊乘</strong>：官方原文 &quot;These multipliers stack with other pricing modifiers such as the Batch API discount&quot;（prompt-caching docs 親驗）→ cache read 0.1× × batch 0.5× = <strong>0.05×</strong>（節省 95%）。</li><li>Gemini 2.5 Pro &gt;200k 輸入標準價從 $1.25/M 升至 $2.50/M，但 cache read 仍 $0.25/M — <strong>context 越長，cache miss 的邊際成本越高，caching 收益越大</strong>。</li><li><strong>Placement 鐵律</strong>：靜態大文件放 cache breakpoint <em>之前</em>，動態 query 放<em>之後</em>；Anthropic lookback window = 20 blocks，breakpoint 後異動不破壞前段。</li><li><code>2601.06007</code>《Don&#39;t Break the Cache》🟡：500+ agentic session、10k token 系統提示實測 — 節省 41–80% 成本、TTFT 改善 13–31%；但 <strong>naive full-context caching 可能反向劣化 latency</strong>，動態內容必須置於 prompt 末端。</li></ol><h3 id="a-3-thinking-reasoning-blocks-與-caching-🟢" tabindex="-1">A.3 Thinking / Reasoning Blocks 與 Caching 🟢 <a class="header-anchor" href="#a-3-thinking-reasoning-blocks-與-caching-🟢" aria-label="Permalink to &quot;A.3 Thinking / Reasoning Blocks 與 Caching 🟢&quot;">​</a></h3><ol><li>Thinking blocks <strong>不能直接標 <code>cache_control</code></strong>，但作為多輪對話前輪內容會被連帶快取；從 cache 讀出計為 input tokens。</li><li><strong><code>budget_tokens</code> / thinking 參數任何變更 → message-level cache miss</strong>（system prompt 層不受影響）。Opus 4.7+ 已棄用 <code>budget_tokens</code>，改 <code>thinking: {type: &quot;adaptive&quot;}</code> + effort 控深度（傳 budget_tokens 返回 400）🟢。</li><li><strong>模型分代差異</strong>：Opus 4.5+ / Sonnet 4.6+ 加入非 tool-result 用戶內容後 thinking blocks <strong>保留</strong>（cache 有效）；舊版及所有 Haiku <strong>自動清除</strong>（cache 失效）。</li><li>Extended thinking 任務官方建議 <strong>1h TTL</strong>（5min 可能在 thinking 完成前過期）。</li><li>🟠 GitHub issue <code>anthropics/claude-code#20249</code>：舊文件曾誤載「thinking 永遠 strip」，Opus 4.5 實為 preserve，文件已更正 — <strong>模型升代後行為會反轉，舊知識誤導 cache 設計</strong>。</li></ol><h3 id="a-4-cache-作為生產健康指標-既有-bp28-整合-🟠" tabindex="-1">A.4 Cache 作為生產健康指標（既有 BP28 整合）🟠 <a class="header-anchor" href="#a-4-cache-作為生產健康指標-既有-bp28-整合-🟠" aria-label="Permalink to &quot;A.4 Cache 作為生產健康指標（既有 BP28 整合）🟠&quot;">​</a></h3><ul><li><code>cache_hit_rate = cache_read_input_tokens / input_tokens</code>，是長跑 agentic 產品的 incident 級指標，<strong>下降即觸發 incident</strong>。</li><li>四層穩定前綴結構：<code>system + tools</code> &gt; 專案檔 &gt; session context &gt; 對話訊息。</li><li>動態資訊用 <code>&lt;system-reminder&gt;</code> tag 經 messages 注入，<strong>不污染 system prompt</strong>。</li><li>Mid-session 切換模型 = 全部 cache 失效（cache 是 model-specific）。Compact 必須使用<strong>完全相同</strong>的 system prompt + tools。</li></ul><h3 id="a-5-既有材料對接" tabindex="-1">A.5 既有材料對接 <a class="header-anchor" href="#a-5-既有材料對接" aria-label="Permalink to &quot;A.5 既有材料對接&quot;">​</a></h3><ul><li><code>2510.04618</code> ACE 🟡：增量 delta playbook → 91.8% KV cache reuse、帳單成本 -82.6%；delta 結構與 cache reuse 天然相容。</li><li><code>2603.04814</code> Beyond Context Window 🟡：long-context 準確率高 33.4–35.2pp，但 ~10 turn 後 memory 成本更划算（20 turn 省 26%）— caching 改變這條 break-even 曲線（cache 讓 long-context 在更多 turn 下仍經濟）。</li></ul><hr><h2 id="section-b-prompt-management-—-缺口最大、roi-最高" tabindex="-1">Section B：Prompt Management — 缺口最大、ROI 最高 <a class="header-anchor" href="#section-b-prompt-management-—-缺口最大、roi-最高" aria-label="Permalink to &quot;Section B：Prompt Management — 缺口最大、ROI 最高&quot;">​</a></h2><blockquote><p>既有材料對此幾乎空白。以下為本報告新增的核心貢獻。</p></blockquote><h3 id="b-1-versioning-registry-governance-工具地景-🟢🟠" tabindex="-1">B.1 Versioning / Registry / Governance 工具地景 🟢🟠 <a class="header-anchor" href="#b-1-versioning-registry-governance-工具地景-🟢🟠" aria-label="Permalink to &quot;B.1 Versioning / Registry / Governance 工具地景 🟢🟠&quot;">​</a></h3><table tabindex="0"><thead><tr><th>工具</th><th>版本機制</th><th>環境分離</th><th>CI gate</th><th>rollback</th><th>開源</th><th>現況</th></tr></thead><tbody><tr><td><strong>Langfuse</strong> 🟢</td><td>遞增 version ID + 自訂 label</td><td>label（production/staging）</td><td>—</td><td>重指派 label</td><td>✅ 功能最完整開源</td><td>活躍</td></tr><tr><td><strong>Braintrust</strong> 🟠</td><td>content-addressable（內容→ID）</td><td>dev/staging/prod</td><td>✅ 唯一 GitHub Actions eval gate</td><td>即時</td><td>❌</td><td>活躍</td></tr><tr><td><strong>Helicone</strong> 🟢</td><td>6 字元 prompt_id + environment</td><td>prod/staging/dev</td><td>—</td><td>UI（API 文件不全）</td><td>部分</td><td>活躍</td></tr><tr><td><strong>LangSmith</strong> 🟠</td><td>commit-hash 式</td><td>—</td><td>—</td><td>—</td><td>❌ managed-only</td><td>vendor lock-in 疑慮</td></tr><tr><td><strong>PromptLayer</strong> 🟠</td><td>passive capture（每次 call 建版）</td><td>—</td><td>git-style</td><td>branch/review</td><td>Enterprise 限</td><td>活躍</td></tr><tr><td><strong>MLflow 3.4</strong> 🟠</td><td>Model Registry 存 prompt</td><td>—</td><td>—</td><td>—</td><td>✅</td><td>評估器少</td></tr><tr><td><strong>Humanloop</strong> 🟠</td><td>reviewer/approve workflow</td><td>deployment vars</td><td>—</td><td>—</td><td>❌</td><td><strong>已 sunset 2025-09-08</strong></td></tr></tbody></table><p><strong>Prompt-as-Code 最佳實踐</strong> 🟠：</p><ul><li>Prompt 存獨立 YAML/JSON 納入 Git，<strong>不散落在應用碼</strong>。</li><li>Deploy webhook → <code>repository_dispatch</code> → GitHub Actions → 自動開 PR（<code>peter-evans/create-pull-request</code>）。</li><li>Eval gate：分數低於門檻 <code>exit 1</code> 封鎖 merge（與 unit test 同級機制）。</li><li>已知缺口：Agenta / Prompt Flow 只能版本控制整個 application variant，<strong>無法版本控制個別 prompt</strong>。</li></ul><h3 id="b-2-prompt-a-b-testing-框架-🟠🟢" tabindex="-1">B.2 Prompt A/B Testing 框架 🟠🟢 <a class="header-anchor" href="#b-2-prompt-a-b-testing-框架-🟠🟢" aria-label="Permalink to &quot;B.2 Prompt A/B Testing 框架 🟠🟢&quot;">​</a></h3><ol><li><strong>流量分配</strong>：Canary（5% → variant B）或 Shadow（同 request 雙跑、用戶只看 control、variant 非同步 log）— shadow 是零用戶風險的離線比較。</li><li><strong>統計方法</strong> 🟢：連續指標 → t-test；二元結果 → chi-square / two-proportion z-test。<strong>早停是 false-positive 膨脹的頭號來源</strong>，需累積 1–3 週樣本。</li><li><strong>三類指標</strong>：Automated（LLM-as-judge：relevance/faithfulness）、Human（thumb、regeneration 等隱性信號）、Operational（latency / token cost）。</li><li><strong>Guardrail metrics</strong>：主指標外必設防護指標，防未測維度退化；同一用戶全程同 variant 避免污染。</li></ol><h3 id="b-3-prompt-injection-安全-🟢🟡" tabindex="-1">B.3 Prompt Injection / 安全 🟢🟡 <a class="header-anchor" href="#b-3-prompt-injection-安全-🟢🟡" aria-label="Permalink to &quot;B.3 Prompt Injection / 安全 🟢🟡&quot;">​</a></h3><ol><li><strong>OWASP LLM01 連續兩版排名第一</strong> 🟢：根因是 LLM 在同一 channel 處理 instruction 與 data，無結構性隔離 → <strong>無 100% 防禦，需 defense-in-depth</strong>。</li><li>管理層防禦：input validation + allowlist + anomaly detection；system prompt 隔離不信任外部內容；RBAC/ABAC 控管誰能改 prompt 配置；SIEM 監控；上線前 red-team + fuzz。</li><li><strong>RAG 擴大攻擊面</strong> 🟡：外部知識庫成為 indirect injection 向量，傳統 sanitizer 不足（<code>2507.13169</code> Prompt Injection 2.0）。</li><li><strong><code>2505.06311</code> InstructDetector</strong>（已全文歸檔）🟡：transformer 中間層（Llama-3.1-8B 第 14 層）hidden states + gradients → MLP 分類器，於資料進 LLM 前過濾。<strong>in-domain 99.60%、out-of-domain 96.90%、BIPIA 攻擊成功率降至 0.03%</strong>，僅需 200 訓練樣本、跨語言/架構泛化。目前實測最強且工程可部署。</li><li>補充防禦：<code>2510.08829</code> CommandSans（surgical sanitization 低誤殺）、<code>2510.05244</code> Minimizer-Sanitizer firewall（有限 privilege LLM 先 filter）🟡。</li></ol><h3 id="b-4-cross-model-migration-playbook-🟠🟡" tabindex="-1">B.4 Cross-Model Migration Playbook 🟠🟡 <a class="header-anchor" href="#b-4-cross-model-migration-playbook-🟠🟡" aria-label="Permalink to &quot;B.4 Cross-Model Migration Playbook 🟠🟡&quot;">​</a></h3><ol><li><strong>三階段 Shadow Deployment</strong> 🟠：Phase 1 並行執行（1–2 週，用戶只看舊模型）→ Phase 2 自動比對（語意相似度 + JSON 合規 + 行為差異分類）→ Phase 3 差異分桶（Improvement / Neutral / Regression / Novel）。</li><li><strong>格式偏好</strong> 🟠：OpenAI 偏 markdown + delimiters；Claude 偏 XML tags；Gemini 偏 constraints-first。核心原則 <strong>re-express ≠ translate</strong>（抽 intent 用目標慣例重寫，不做 find-replace）。</li><li><strong>Hardest cases first</strong> 🟠：舊模型上迭代最多次的 prompt 遷移後最易崩，優先測；embedding index 須完整重建（向量空間不相容）。</li><li><strong><code>2512.01420</code> PromptBridge</strong>（已全文歸檔，PDF 第 1 頁親驗）🟡：提出 <strong>Model Drifting</strong> 現象（prompt 跨模型重用嚴重劣化）；MAP-RPE 兩階段 — calibration（少量 alignment pair 學 source/target 映射）+ transfer（test-time 直接轉，無需 per-task 重優化），<strong>training-free</strong>。轉移到 o3 時相對 direct transfer：<strong>SWE-Bench +27.39%、Terminal-Bench +39.44%</strong>（原文 abstract 數字）。作者 UC Santa Cruz × Accenture Center for Advanced AI。</li><li><strong>反模式</strong> 🟠：避免建跨 provider 的「prompt normalization layer」— model-specific prompt 持續優於 generic，abstraction 的可移植性以效能為代價。</li></ol><hr><h2 id="section-c-prompt-engineering-—-隨模型能力反轉" tabindex="-1">Section C：Prompt Engineering — 隨模型能力反轉 <a class="header-anchor" href="#section-c-prompt-engineering-—-隨模型能力反轉" aria-label="Permalink to &quot;Section C：Prompt Engineering — 隨模型能力反轉&quot;">​</a></h2><h3 id="c-1-non-gpt-non-math-驗證-prompting-inversion-在-claude-成立-🟢" tabindex="-1">C.1 Non-GPT / Non-math 驗證：Prompting Inversion 在 Claude 成立 🟢 <a class="header-anchor" href="#c-1-non-gpt-non-math-驗證-prompting-inversion-在-claude-成立-🟢" aria-label="Permalink to &quot;C.1 Non-GPT / Non-math 驗證：Prompting Inversion 在 Claude 成立 🟢&quot;">​</a></h3><p>既有 <code>2510.22251</code> 只測 GPT + GSM8K（gpt-5 上 constrained CoT 反轉 -2.36%）。本報告以 Anthropic 官方一手補齊外部效度：</p><ol><li><strong>字面化成立</strong>：Opus 4.8 低 effort 下嚴格字面解讀，<em>不靜默泛化</em>（官方原文 &quot;It does not silently generalize an instruction from one item to another.&quot;）。修正：明確寫 scope（&quot;Apply to every section, not just the first.&quot;）。<strong>機制是 effort 參數，不是 token budget 壓縮</strong>。</li><li><strong>Effort &gt; Prompt</strong>：&quot;Effort is likely to be more important for this model than for any prior Opus.&quot; → <strong>shallow reasoning 先升 effort（high/xhigh），再考慮 prompt 補丁</strong>。</li><li>Adaptive Thinking 取代 budget_tokens；Opus 4.8 預設 effort = <code>high</code>（4.7 為 <code>medium</code>）。</li><li><strong>Positive &gt; Negative 官方驗證</strong>：&quot;Positive examples ... tend to be more effective than negative examples or instructions that tell the model what not to do.&quot;（直引）— 與本 harness output-discipline.md「正向指令優先」一致。</li><li><strong>Gemini</strong> 🟢：PTCF 框架（Persona·Task·Context·Format）；官方「always include few-shot」；Gemini 3 強建議 temperature=1.0（低於會異常）。</li></ol><h3 id="c-2-structured-outputs-tool-use-forcing-🟢🟠" tabindex="-1">C.2 Structured Outputs / Tool-use Forcing 🟢🟠 <a class="header-anchor" href="#c-2-structured-outputs-tool-use-forcing-🟢🟠" aria-label="Permalink to &quot;C.2 Structured Outputs / Tool-use Forcing 🟢🟠&quot;">​</a></h3><ol><li><strong>Anthropic Native Structured Outputs（GA）</strong>：beta header <code>structured-outputs-2025-11-13</code> + <code>output_format: {type: &quot;json_schema&quot;}</code>，grammar-constrained decoding，<strong>保證格式合規但不保證內容正確</strong>。</li><li><strong>已知陷阱</strong>：Anthropic SDK 靜默把 <code>minimum/maximum/minLength/pattern</code> 移到 description，validate 失敗才重試。</li><li><code>tool_choice: &quot;any&quot;</code> 比 <code>&quot;auto&quot;</code> 省 ~33 tokens；tool description 越短越省。</li><li><strong>JSON mode 已過時</strong>：constrained decoding 上線後，舊式「prompt 求 JSON 並祈禱」成 footnote。</li><li>固定 schema pipeline 應 cache schema，避免每次重傳計費（與 Section A 對接）。</li></ol><h3 id="c-3-rag-prompting-整合-🟡🟠" tabindex="-1">C.3 RAG + Prompting 整合 🟡🟠 <a class="header-anchor" href="#c-3-rag-prompting-整合-🟡🟠" aria-label="Permalink to &quot;C.3 RAG + Prompting 整合 🟡🟠&quot;">​</a></h3><ol><li><strong>Lost-in-the-Middle 量化</strong> 🟡：U 型注意力，相關資訊移至中間效能降 &gt;30%；解法 — 重要文件放開頭/結尾，<strong>零成本大幅提升</strong>。</li><li><strong>Chunk size 依領域</strong>：專利 1,000–1,500 tokens；對話記錄 200–400；無普遍最優。</li><li><strong>Dynamic k</strong>（<code>2512.14313</code>）：動態預測最優文件數優於固定 k；k 太多引入 distractor，太少召回不足。</li><li><strong>Contrastive ICL-RAG</strong>（<code>2501.07391</code> ACL 2025，已全文歸檔）🟡：prompt 中同提供正確 + 對比反例，助模型區分相關/無關 context。</li><li><strong>Context Quality &gt; Model Optimization</strong>：&quot;RAG is only as good as the context it can see&quot; — ungoverned / stale context 無法靠模型優化補救。</li></ol><h3 id="c-4-agentic-prompt-regression-testing-🟢🟡" tabindex="-1">C.4 Agentic Prompt Regression Testing 🟢🟡 <a class="header-anchor" href="#c-4-agentic-prompt-regression-testing-🟢🟡" aria-label="Permalink to &quot;C.4 Agentic Prompt Regression Testing 🟢🟡&quot;">​</a></h3><ol><li><strong>&quot;Better Prompts Hurt&quot; 量化</strong>（<code>2601.22025</code>，已全文歸檔）🟡：泛用 prompt 取代 task-specific → extraction pass rate 100%→90%、RAG compliance 93.3%→80%（Llama 3）。結論：<strong>context-specific evaluation 必須先於 prompt 修改，不存在普遍最優 prompt</strong>。直接呼應本 harness §R9（Tests Verify Intent）。</li><li><strong>MVES（Minimum Viable Evaluation Suite）</strong>：分三類（一般 / RAG / Agentic tool-use）；成本分層 — cheap deterministic checks → heuristic → LLM-as-judge 最後才用。</li><li><strong>LLM-as-Judge + rubric</strong>：工具鏈/多輪推理難字串比對，judge + rubric 才有效（promptfoo <code>llm-rubric</code> 自動 pass/fail）。</li><li><strong>Prompt-as-Code Regression CI</strong>：promptfoo GitHub Action 在 PR 跑 eval、生成 before/after、regression 即 build fail（與 unit test 同級）。</li><li><strong>Agentic eval 雙層</strong>：須同時評「最終答案正確」與「中間推理步驟合理」。</li></ol><hr><h2 id="跨主題綜合-prompt-生命週期流水線" tabindex="-1">跨主題綜合：Prompt 生命週期流水線 <a class="header-anchor" href="#跨主題綜合-prompt-生命週期流水線" aria-label="Permalink to &quot;跨主題綜合：Prompt 生命週期流水線&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[設計] Engineering          [部署] Management           [執行] Caching</span></span>
<span class="line"><span> effort 旋鈕優先      →    版本入 Git + label      →   穩定前綴 + breakpoint</span></span>
<span class="line"><span> positive&gt;negative        eval gate (CI)              cache_hit_rate 監控</span></span>
<span class="line"><span> structured output        A/B (shadow/canary)        TTL 配 use-case</span></span>
<span class="line"><span> RAG: 重要放頭尾          注入防禦 (InstructDetector)  mid-session 不切模型</span></span>
<span class="line"><span> eval-driven 迭代         cross-model: re-express     thinking 用 1h TTL</span></span>
<span class="line"><span>       │                        │                          │</span></span>
<span class="line"><span>       └──────────── 三者皆以「靜態優先、動態末端」為共同原則 ───────────┘</span></span></code></pre></div><p><strong>唯一最重要的單一原則</strong>：<strong>靜態前綴穩定</strong>同時是 caching 的省錢機制（A.4）、management 的版本可追溯基礎（B.1）、engineering 的字面化可預測前提（C.1）。三主題在此交會。</p><hr><h2 id="仍待研究的方向-誠實標注" tabindex="-1">仍待研究的方向（誠實標注） <a class="header-anchor" href="#仍待研究的方向-誠實標注" aria-label="Permalink to &quot;仍待研究的方向（誠實標注）&quot;">​</a></h2><ol><li>Prompting-inversion 在 Claude 上<strong>僅有官方定性說法</strong>，缺 GSM8K 等 benchmark 的量化反轉曲線（GPT 有，Claude 無）。</li><li>Caching + memory（ACE delta）+ long-context 三者的<strong>聯合成本模型</strong>尚無單一論文涵蓋。</li><li>InstructDetector 等 hidden-state 防禦對<strong>閉源 API 模型</strong>（無法取 hidden states）不適用，API-only 場景的最強 indirect-injection 防禦仍開放。</li><li><code>2501.07391</code> arXiv 版為 2 頁短摘要，完整 RAG best-practice 數字需查 ACL 2025 proceedings 全文。</li></ol><hr><h2 id="來源清單" tabindex="-1">來源清單 <a class="header-anchor" href="#來源清單" aria-label="Permalink to &quot;來源清單&quot;">​</a></h2><p><strong>既有材料（build on）</strong>：</p><ul><li><code>papers/2026-01-31-dont-break-cache-prompt-caching-2601-06007.md</code></li><li><code>papers/2025-10-06-agentic-context-engineering-2510-04618.md</code></li><li><code>papers/2025-10-25-prompting-inversion-2510-22251.md</code></li><li><code>papers/2025-08-01-rcr-router-role-aware-context-routing-2508.04903.md</code></li><li><code>papers/2026-03-05-beyond-context-window-memory-vs-longcontext-2603-04814.md</code></li><li><code>best-practices/05-claude-prompting-best-practices.md</code></li><li><code>best-practices/08-prompt-caching.md</code></li><li><code>best-practices/28-thariq-prompt-caching-lessons.md</code></li></ul><p><strong>本次新收全文論文（research/papers/，PDF + md）</strong>：</p><ul><li><code>2026-01-29-when-better-prompts-hurt-eval-driven-2601-22025</code>（MVES / eval-driven）</li><li><code>2025-05-08-indirect-prompt-injection-defense-2505-06311</code>（InstructDetector）</li><li><code>2025-12-01-promptbridge-cross-model-prompt-transfer-2512-01420</code>（cross-model）</li><li><code>2025-01-13-rag-best-practices-acl2025-2501-07391</code>（ACL 2025 RAG）</li></ul><p><strong>官方一手 docs</strong>：Anthropic Pricing / Prompt Caching / Extended Thinking / Prompting Best Practices / What&#39;s New Opus 4.8；OpenAI Prompt Caching + Structured Outputs；Google Gemini Pricing + Prompting Strategies + implicit caching blog。</p><p><strong>社群二手（明標）</strong>：Braintrust / Langfuse / Helicone / Nearform / ZenML / Agenta / Traceloop / Statsig / TianPan.co migration playbook；GitHub <code>anthropics/claude-code#20249</code>；OWASP LLM Top 10 2025（CSA）。</p>`,61)])])}const m=e(i,[["render",a]]);export{h as __pageData,m as default};
